for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")

    # Let's look at character by character differences
    min_len = min(len(inp), len(outp))
    print(f"  Length: {len(inp)} -> {len(outp)}")
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
    if len(inp) > len(outp):
        print(f"  Removed chars at positions {len(outp)}-{len(inp)-1}")
    elif len(outp) > len(inp):
        print(f"  Added chars at positions {len(inp)}-{len(outp)-1}")
    print()

